import json, sys, copy
from pathlib import Path
rv = Path("/home/user/aicfinal_test/cases/MU-0000723125-26-000023/rounds/round-001/reviews/review-01")
req = json.loads((rv/"request.json").read_text())
RID, CID = req["request_id"], req["candidate_id"]
prefix = {"crit-provenance":"prov-","crit-assumption":"asm-","crit-compliance":"cmp-"}
problems, reports, findings, checks = [], [], [], {}
for role in req["required_reports"]:
    d = json.loads((rv/f"{role}.json").read_text())
    for k in ["request_id","role","candidate_id","verdict","findings","resolved","checked"]:
        if k not in d: problems.append(f"{role}: missing {k}")
    if d["request_id"]!=RID: problems.append(f"{role}: request_id {d['request_id']}")
    if d["candidate_id"]!=CID: problems.append(f"{role}: candidate_id {d['candidate_id']}")
    if d["role"]!=role: problems.append(f"{role}: role {d['role']}")
    if d["verdict"] not in ("pass","fail"): problems.append(f"{role}: verdict")
    blocking=[f["id"] for f in d["findings"] if f["severity"] in ("blocker","major")]
    if d["verdict"]=="pass" and blocking: problems.append(f"{role}: pass with blocking {blocking}")
    for f in d["findings"]:
        for k in ["id","severity","title","detail","evidence","required_evidence"]:
            if k not in f: problems.append(f"{role}/{f.get('id')}: missing {k}")
        if not f["id"].startswith(prefix[role]): problems.append(f"{role}: bad prefix {f['id']}")
        if f["severity"] not in ("blocker","major","minor"): problems.append(f"{role}/{f['id']}: severity {f['severity']}")
        g = copy.deepcopy(f); g["source_role"]=role; findings.append(g)
    reports.append({"role":role,"file":f"{role}.json","verdict":d["verdict"],
                    "finding_ids":[f["id"] for f in d["findings"]],"resolved":d["resolved"]})
    checks[role]=d["checked"]
print("problems:", problems)
ids=[f["id"] for f in findings]; assert len(ids)==len(set(ids))
conflicts=[
 {"ids":["prov-001","cmp-002"],"type":"severity disagreement",
  "note":"Same defect (pipe characters inside verbatim quotes Q-1..Q-4 break the guidance table in note_rendered.md). crit-provenance rates it major (truncated quotes, quote-to-code-value evidence trail broken); crit-compliance rates it minor (presentation defect, figures correct). Both findings kept at their own severity; the higher (major) blocks. Required evidence differs slightly: prov-001 asks for exactly three cells per row and whole quotes (e.g. split GAAP/non-GAAP quotes); cmp-002 accepts a list or escaped pipes."},
 {"ids":["asm-001","prov-004","cmp-003"],"type":"overlap with differing scope and remedy",
  "note":"All three concern the $30,019M long-term marketable investments (periodic.txt line 2032) left out of net cash and the note's sentence that the rating 'would stay Neutral' per 'the valuation specialist'. asm-001 (major) treats the omission itself as a valuation error and requires remapping the investments line, recomputing net_cash (68,274M) and dropping the uncomputed rating claim. prov-004 (minor) and cmp-003 (minor) address only how the sentence is evidenced and accept keeping it if labelled as analyst calculation or backed by a code value or quote; prov-004 explicitly leaves the net-cash definition to crit-assumption. Their own arithmetic agrees the rating stays Neutral (upside about 7.1% asm-001, about 7.2% prov-004, about 7% cmp-003). Remedies are compatible only if asm-001's fix is made; satisfying prov-004/cmp-003 alone would not close asm-001. All kept unchanged."}
]
blocking=[f["id"] for f in findings if f["severity"] in ("blocker","major")]
merged={"request_id":RID,"candidate_id":CID,"case_id":req["case_id"],"round":req["round"],"review":req["review"],
 "reports":reports,"findings":findings,"conflicts":conflicts,"blocking_findings":blocking,
 "overall":"fail" if blocking or any(r["verdict"]=="fail" for r in reports) else "pass",
 "coverage":{"checks_by_critic":checks,
  "acceptance_areas":{
   "A_numerical_gates":"gates.json reviewed by crit-provenance (no findings; recompute hashes and computed/ copies match) and crit-compliance (no findings); information cutoff checked independently by provenance and compliance; quote verbatim re-checked by compliance; guidance values vs quotes by provenance; assumption bounds/rationales by assumption",
   "B_critic_review":"three critics reported for this request_id and candidate_id; open_findings empty, nothing to resolve",
   "C_research_acceptance":"not met this review: all three critics return fail; blocking findings prov-001, asm-001, cmp-001",
   "D_publication_rating_policy":"rating band (upside 4.65% -> Neutral), target price match and TP-change-rationale flag checked by crit-compliance; policy section 6 disclosures checked by crit-compliance (cmp-001); approval itself is outside critic scope",
   "E_limits":"controller-owned; not a critic check"},
  "uncovered_areas":[],
  "verification_notes":[
   "All three reports carry request_id crit-20261115T080121-5bb2e2, candidate_id cand-b70a3fbcac71, the correct role, verdict in {pass, fail}, the contract fields (findings, resolved, checked) and correct ID prefixes; each fail verdict is consistent with at least one major finding.",
   "These reports were produced by critics dispatched in an earlier crit-lead run for this same request; this run did not re-dispatch (resumed dispatch).",
   "cmp-003 cites cases/MU-0000723125-26-000023/RUN_NOTES.md (a case-level run log, outside snapshot/ and the round files) as evidence. The fact it relies on (AvailableForSaleSecuritiesDebtSecuritiesNoncurrent 30,019M, F-5368223b24) resolves in snapshot/facts.json and is independently cited by asm-001 and prov-004 from periodic.txt line 2032, so the finding stands on snapshot evidence; RUN_NOTES contains no earlier critic opinions for this case. Recorded for transparency only; the finding is unchanged."]}}
if problems: sys.exit("not writing: "+"; ".join(problems))
(rv/"merged.json").write_text(json.dumps(merged,indent=2,ensure_ascii=False)+"\n")
print("written", len(findings), blocking)
EOF
